# 04_analysis.R: tables answering the six questions, ALWAYS pairing like with like:
#   abundance representation: LCBD (Hellinger, abundance), LCZD (relative abundance), T / T+ (relative abundance)
#   occurrence representation: LCBD (Hellinger of presence-absence), LCZD (incidence), T / T+ (occurrence)
# Tree-record data principal; stems as sensitivity. All zeta quantities are exact/analytical zetaGDUM outputs.
source("bci_lib.R"); options(width = 220); S <- readRDS("out/site_metrics.rds"); B <- readRDS("out/bci_matrices.rds"); h <- B$habitat; K <- c(2, 3, 4, 5, 8, 12, 20, 40, 80, 160, 320, 640)
source("merge_norm.R"); S <- add_norm(S); S$swamp <- S$habitat == "swamp"; pr <- function(v) rank(v, na.last = "keep") / sum(is.finite(v)); rho <- function(a, b) cor(a, b, method = "spearman", use = "complete.obs")
top <- function(v, p = .1) { if (all(is.na(v))) return(rep(NA, length(v))); v >= quantile(v, 1 - p, na.rm = TRUE) }; jac <- function(a, b) sum(a & b, na.rm = TRUE) / sum(a | b, na.rm = TRUE); cliff <- function(a, b) { m <- outer(a, b, "-"); (sum(m > 0) - sum(m < 0)) / length(m) }
REP <- list(abundance = list(lcbd = "LCBD_hel", lczd = "LCZD_rel_", ed = "ED_rel_", T = "T_rel", Tp = "T_plus_rel", z2 = "zeta2_rel", ty = "relative"), occurrence = list(lcbd = "LCBD_hel_occ", lczd = "LCZD_norm_", ed = "ED_norm_", T = "T_occ", Tp = "T_plus_occ", z2 = "zeta2_occ", ty = "incidence"))
Q1 <- list(); Q4 <- list(); Q3 <- list(); Q3b <- list(); Q2v <- list(); Q2p <- list(); Q5 <- list(); Q5oh <- list(); Q0 <- list()
for (nm in unique(S$set)) { d <- S[S$set == nm, ]; x <- B$mat[[nm]]; x <- x[, colSums(x) > 0]; stopifnot(identical(rownames(x), d$quad))
  Q0[[nm]] <- data.frame(set = nm, rho_LCBD_abundance_vs_occurrence = rho(d$LCBD_hel, d$LCBD_hel_occ), rho_T_abundance_vs_occurrence = rho(d$T_rel, d$T_occ), rho_Tplus_abundance_vs_occurrence = rho(d$T_plus_rel, d$T_plus_occ), top10_overlap_LCBD = jac(top(d$LCBD_hel), top(d$LCBD_hel_occ)), swamp_in_top10_LCBD_abund = mean(top(d$LCBD_hel)[d$swamp]), swamp_in_top10_LCBD_occ = mean(top(d$LCBD_hel_occ)[d$swamp]))
  for (rn in names(REP)) { R <- REP[[rn]]; lb <- d[[R$lcbd]]
    for (k in K) { other <- REP[[setdiff(names(REP), rn)]]; if (!any(is.finite(d[[paste0(R$lczd, k)]]))) next; lz <- d[[paste0(R$lczd, k)]]; lzo <- d[[paste0(other$lczd, k)]]; if (is.null(lzo) || !any(is.finite(lzo))) lzo <- rep(NA_real_, length(lz))
      Q1[[length(Q1) + 1]] <- data.frame(set = nm, representation = rn, order = k, rho_LCBD_LCZD = rho(lb, lz), top10_LCBD_in_top10_LCZD = mean(top(lz)[top(lb)], na.rm = TRUE), swamp_rank_pct_LCBD = mean(pr(lb)[d$swamp]), swamp_rank_pct_LCZD = mean(pr(lz)[d$swamp], na.rm = TRUE), swamp_in_top10_LCZD = mean(top(lz)[d$swamp], na.rm = TRUE), rho_LCBD_vs_LCZD_other_representation = if (any(is.finite(lzo))) rho(lb, lzo) else NA_real_, rho_LCBD_vs_LCZD_incidence_unnormalised = if (rn == "occurrence") rho(lb, d[[paste0("LCZD_inc_", k)]]) else NA_real_, swamp_rank_pct_LCZD_incidence_unnormalised = if (rn == "occurrence") mean(pr(d[[paste0("LCZD_inc_", k)]])[d$swamp]) else NA_real_) }
    vars <- c(R$lcbd, paste0(R$lczd, c(2, 20, 80)), R$T, R$Tp, R$z2)
    Q3[[length(Q3) + 1]] <- d |> group_by(set, habitat) |> summarise(representation = rn, n = n(), across(all_of(vars), list(median = ~ median(., na.rm = TRUE), q25 = ~ quantile(., .25, na.rm = TRUE), q75 = ~ quantile(., .75, na.rm = TRUE))), .groups = "drop")
    Q3b[[length(Q3b) + 1]] <- bind_rows(lapply(vars, function(v) data.frame(set = nm, representation = rn, variable = v, swamp_median = median(d[[v]][d$swamp], na.rm = T), rest_median = median(d[[v]][!d$swamp], na.rm = T), cliffs_delta = cliff(d[[v]][d$swamp], d[[v]][!d$swamp]))))
    for (v in c(R$T, R$Tp, R$z2)) { f <- loess(d[[v]] ~ lb, span = .5); r <- residuals(f); Q2v[[length(Q2v) + 1]] <- data.frame(set = nm, representation = rn, variable = v, rho_with_matching_LCBD = rho(lb, d[[v]]), R2_loess_on_matching_LCBD = 1 - var(r) / var(d[[v]]), resid_sd = sd(r), plotwide_range_q05_q95 = diff(quantile(d[[v]], c(.05, .95)))) }
    ord <- order(lb); bins <- split(ord, ceiling(seq_along(ord) / 25))
    for (b in bins) for (v in c(R$T, R$Tp)) { vv <- d[[v]][b]; Q2p[[length(Q2p) + 1]] <- data.frame(set = nm, representation = rn, bin_LCBD_median = median(lb[b]), bin_LCBD_range_pct = 100 * diff(range(lb[b])) / median(lb[b]), variable = v, bin_min = min(vv, na.rm = T), bin_max = max(vv, na.rm = T), bin_range = diff(range(vv, na.rm = T)), n_swamp = sum(d$swamp[b])) }
    for (k in K) { lr <- d[[paste0(R$lczd, k)]]; lo <- d[[paste0(REP[[setdiff(names(REP), rn)]]$lczd, k)]]; if (!any(is.finite(lr)) || !any(is.finite(lo))) next; if (rn == "abundance") Q4[[length(Q4) + 1]] <- data.frame(set = nm, order = k, rho_LCZD_abund_vs_occ = rho(lr, lo), jaccard_top10 = jac(top(lr), top(lo)), jaccard_top10_swamp_excluded = jac(top(lr)[!d$swamp], top(lo)[!d$swamp])) }
    for (k in c(2, 10, 40)) { sl <- species_local(x, k, R$ty)
      for (g in c("swamp", "rest")) { ii <- if (g == "swamp") d$swamp else !d$swamp
        Q5[[length(Q5) + 1]] <- data.frame(set = nm, order = k, type = R$ty, group = g, species = colnames(x), contribution = colMeans(sl$C[ii, , drop = FALSE]), occupancy_part = colMeans(sl$O[ii, , drop = FALSE]), heterogeneity_part = colMeans(sl$H[ii, , drop = FALSE]), occ_all = colMeans(x > 0), occ_group = colMeans(x[ii, , drop = FALSE] > 0), mean_q_group = colMeans(sl$q[ii, , drop = FALSE]), mean_q_other = colMeans(sl$q[!ii, , drop = FALSE]), region_occupancy = colSums(x > 0)) }
      for (hb in unique(d$habitat)) { ii <- d$habitat == hb; Q5oh[[length(Q5oh) + 1]] <- data.frame(set = nm, order = k, type = R$ty, habitat = hb, expected_dissimilarity = mean(rowSums(sl$C[ii, , drop = FALSE])), occupancy_part = mean(rowSums(sl$O[ii, , drop = FALSE])), heterogeneity_part = mean(rowSums(sl$H[ii, , drop = FALSE]))) } } } }
w <- function(l, f) write.csv(bind_rows(l), file.path("tables", f), row.names = FALSE)
Q1 <- lapply(Q1, function(r) r); w(Q0, "q0_abundance_vs_occurrence_local_metrics.csv"); w(Q1, "q1_persistence_across_orders.csv"); w(Q4, "q4_LCZD_abundance_vs_incidence.csv"); w(Q3, "q3_habitat_summary.csv"); w(Q3b, "q3_swamp_vs_rest.csv"); w(Q2v, "q2_variance_in_retention_explained_by_LCBD.csv"); w(Q2p, "q2_LCBD_bins_retention_range.csv"); w(Q5, "q5_species_contributions_swamp_vs_rest.csv"); w(Q5oh, "q5_occupancy_heterogeneity_by_habitat.csv")
# ---- Q2 concrete pairs: nearest-LCBD pairs (within each representation) with the largest contrast in the matching T
pairs <- list(); for (nm in c("1985_tree", "2015_tree")) for (rn in names(REP)) { R <- REP[[rn]]; d <- S[S$set == nm, ]; lb <- d[[R$lcbd]]; o <- order(lb); for (i in seq_len(nrow(d) - 1)) for (j in (i + 1):min(i + 15, nrow(d))) { a <- o[i]; b <- o[j]
    pairs[[length(pairs) + 1]] <- data.frame(set = nm, representation = rn, quad_a = d$quad[a], quad_b = d$quad[b], habitat_a = d$habitat[a], habitat_b = d$habitat[b], LCBD_a = lb[a], LCBD_b = lb[b], dLCBD_pct = 100 * abs(lb[a] - lb[b]) / mean(lb[c(a, b)]), T_a = d[[R$T]][a], T_b = d[[R$T]][b], Tplus_a = d[[R$Tp]][a], Tplus_b = d[[R$Tp]][b], rich_a = d$richness[a], rich_b = d$richness[b], n_a = d$individuals[a], n_b = d$individuals[b]) } }
P <- bind_rows(pairs) |> mutate(dT = abs(T_a - T_b), dTplus = abs(Tplus_a - Tplus_b)); write.csv(P |> filter(dLCBD_pct <= 2) |> arrange(set, representation, desc(dT)) |> group_by(set, representation) |> slice_head(n = 200), "tables/q2_matched_pairs_top.csv", row.names = FALSE)
cat("\nQ0\n"); print(bind_rows(Q0) |> mutate(across(where(is.numeric), ~ round(., 2))))
cat("\nQ1 (1985)\n"); print(bind_rows(Q1) |> filter(set == "1985_tree") |> mutate(across(where(is.numeric), ~ round(., 2))) |> arrange(representation, order))
cat("\nQ2 variance\n"); print(bind_rows(Q2v) |> filter(set %in% c("1985_tree", "2015_tree")) |> mutate(across(where(is.numeric), ~ round(., 2))))
cat("\nQ2 matched pairs (dLCBD<=2%): median|dT| and q95\n"); print(P |> filter(dLCBD_pct <= 2) |> group_by(set, representation) |> summarise(pairs = n(), median_dT = round(median(dT), 2), q95_dT = round(quantile(dT, .95), 2), median_dTplus = round(median(dTplus), 2), q95_dTplus = round(quantile(dTplus, .95), 2), .groups = "drop"))
cat("\nQ3 swamp vs rest\n"); print(bind_rows(Q3b) |> filter(set %in% c("1985_tree", "2015_tree")) |> mutate(across(where(is.numeric), ~ round(., 3))) |> arrange(set, representation))
